from functools import reduce

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a


def lcm(a: int, b: int) -> int:
    return a * b // gcd(a, b)


def maxLength(nums: List[int]) -> int:
    n = len(nums)
    max_len = 0

    for start in range(n):
        current_gcd = nums[start]
        current_lcm = nums[start]
        for end in range(start, n):
            if end > start:
                current_gcd = gcd(current_gcd, nums[end])
                current_lcm = lcm(current_lcm, nums[end])

            current_product = reduce(lambda x, y: x * y, nums[start:end + 1])
            if current_product == current_gcd * current_lcm:
                max_len = max(max_len, end - start + 1)

    return max_len

