def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    for i in range(len(grid)):
        if i % 2 == 0:
            # Traverse right and skip alternate cells
            result.extend(grid[i][j] for j in range(0, len(grid[i]), 2))
        else:
            # Traverse left and skip alternate cells
            result.extend(grid[i][j] for j in range(len(grid[i]) - 1, -1, -2) if j % 2 == 1)
    return result

