def minCost(n: int, cost: List[List[int]]) -> int:
    # Initialize a DP table where dp[i][j] is the minimum cost to paint up to house i with color j
    dp = [[0] * 3 for _ in range(n)]

    # Base cases: Cost of painting the first house with each color
    for j in range(3):
        dp[0][j] = cost[0][j]

    for i in range(1, n):
        for j in range(3):
            # Calculate the minimum cost for painting house i with color j,
            # ensuring we don't paint adjacent houses the same color.
            dp[i][j] = cost[i][j] + min(
                dp[i-1][(j+1) % 3],  # Previous house with different color
                dp[i-1][(j+2) % 3]   # Previous house with different color
            )

    # Minimum cost considering the restrictions
    min_cost = float('inf')
    for j in range(3):
        for k in range(3):
            if j != k:  # Ensure opposite house has a different color
                # Combine the costs of the last house and its opposite
                min_cost = min(min_cost, dp[n-1][j] + dp[n-1 - (n//2)][k])  # Corrected index for the opposite house.

    return min_cost

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    offline_until = [0] * numberOfUsers
    event_dict = []

    for event in events:
        event_dict.append((int(event[1]), event[0], event[2]))

    # Sort events by timestamp
    event_dict.sort(key=lambda x: x[0])

    for timestamp, event_type, detail in event_dict:
        if event_type == "OFFLINE":
            user_id = int(detail)
            offline_until[user_id] = timestamp + 60
        elif event_type == "MESSAGE":
            mentions_in_message = []
            if detail == "ALL":
                mentions_in_message = range(numberOfUsers)
            elif detail == "HERE":
                mentions_in_message = [i for i in range(numberOfUsers) if timestamp >= offline_until[i]]
            else:
                mentions_in_message = [int(id[2:]) for id in detail.split()]

            for user_id in mentions_in_message:
                mentions[user_id] += 1

    return mentions
